svg.script:
const bind = (control, action) => {
  control.addEventListener("click", action);
  control.addEventListener("keydown", event => {
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    if (!event.repeat) action();
  });
};
const root = document.documentElement;
const themeSwitch = root.querySelector(".theme-switch");
const themePreference = matchMedia("(prefers-color-scheme: dark)");
const themeKey = "oliver-portfolio-theme";
let chosenTheme;
try { chosenTheme = localStorage.getItem(themeKey); } catch {}
const applyTheme = () => {
  const dark = chosenTheme === "dark" || (chosenTheme !== "light" && themePreference.matches);
  root.dataset.theme = dark ? "dark" : "light";
  themeSwitch.setAttribute("aria-checked", String(dark));
};
bind(themeSwitch, () => {
  chosenTheme = root.dataset.theme === "dark" ? "light" : "dark";
  try { localStorage.setItem(themeKey, chosenTheme); } catch {}
  applyTheme();
});
themePreference.addEventListener("change", applyTheme);
applyTheme();
root.classList.add("theme-ready");

const timelines = [
  [
    ["El catálogo aporta los conceptos.", 0],
    ["El editor calcula partidas y totales.", 1],
    ["La emisión valida, numera y congela el presupuesto.", 2],
    ["Chromium genera el PDF desde la instantánea."]
  ],
  [
    ["El código está en GitHub.", 0],
    ["Dokploy obtiene el código y ejecuta Compose.", 1],
    ["Compose construye las imágenes y arranca PostgreSQL."],
    ["PostgreSQL listo: pueden empezar las migraciones.", 2],
    ["Prisma aplica las migraciones; si terminan bien, arranca la app.", 3],
    ["La aplicación ya puede consultar PostgreSQL."]
  ]
];
const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
document.querySelectorAll(".diagram").forEach((diagram, index) => {
  const steps = timelines[index];
  const status = diagram.querySelector(".status");
  const nodes = [...diagram.querySelectorAll("[data-step]")];
  const links = [...diagram.querySelectorAll(".signal")];
  const play = diagram.querySelector('[data-action="play"]');
  const pause = diagram.querySelector('[data-action="pause"]');
  const name = index === 0 ? "presupuesto" : "despliegue";
  const stepMs = 1800;
  let elapsed = 0, frame = 0, previous = null, state = "idle", active = -1;
  const label = (control, word) => {
    control.querySelector("text").textContent = word;
    control.setAttribute("aria-label", `${word} ${name}`);
  };
  const show = (time) => {
    const step = Math.min(steps.length - 1, Math.floor(time / stepMs));
    const [message, link] = steps[step];
    if (step !== active) {
      nodes.forEach(node => node.classList.toggle("is-current", Number(node.dataset.step) === step));
      status.textContent = `${step + 1}/${steps.length} · ${message}`;
      active = step;
    }
    const progress = (time - step * stepMs - 1060) / 650;
    links.forEach((path, i) => {
      const inFlight = i === link && progress >= 0 && progress <= 1 && !reducedMotion.matches;
      path.classList.toggle("in-flight", inFlight);
      if (inFlight) path.style.strokeDashoffset = String(22 - 122 * progress);
    });
  };
  const tick = (now) => {
    if (state !== "playing") return;
    if (previous !== null) elapsed += now - previous;
    previous = now;
    show(elapsed);
    if (elapsed >= steps.length * stepMs) {
      state = "finished";
      pause.setAttribute("aria-disabled", "true");
      return;
    }
    frame = requestAnimationFrame(tick);
  };
  const resume = () => {
    state = "playing";
    previous = null;
    label(pause, "Pausar");
    pause.setAttribute("aria-disabled", "false");
    frame = requestAnimationFrame(tick);
  };
  bind(play, () => {
    cancelAnimationFrame(frame);
    elapsed = 0;
    diagram.classList.add("has-step");
    label(play, "Repetir");
    show(elapsed);
    resume();
  });
  bind(pause, () => {
    if (state === "paused") return resume();
    if (state !== "playing") return;
    state = "paused";
    cancelAnimationFrame(frame);
    label(pause, "Continuar");
  });
  diagram.classList.add("is-ready");
});
